from taf.gnb.oam.coam.cu.utilities.http_client import HttpClient


class FMLicensedv1HttpClient(HttpClient):
    """ This class provides a client for the FM Licensed v1 API. """

    def __init__(self, base_url, connection_alias):
        super(FMLicensedv1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def get_historical_alarms(self, timeout=30, page_number=None, items_per_page=None, sorted_by="appearTime",
                              sort_order="desc", filter_by_severity=None, filter_by_alarming_object=None,
                              filter_by_text=None):
        endpoint = '/alarms/historical'
        payload = self._get_payload_for_alarms(page_number, items_per_page, sorted_by, sort_order, filter_by_severity,
                                               filter_by_alarming_object, filter_by_text)
        headers = {
            "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def get_active_alarms(self, timeout=30, page_number=None, items_per_page=None, sorted_by="appearTime",
                          sort_order="desc", filter_by_severity=None, filter_by_alarming_object=None,
                          filter_by_text=None):
        endpoint = '/alarms/active'
        payload = self._get_payload_for_alarms(page_number, items_per_page, sorted_by, sort_order, filter_by_severity,
                                                 filter_by_alarming_object, filter_by_text)
        headers = {
                "Content-Type": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, payload=payload, timeout=timeout, headers=headers)

    def get_active_alarms_summary(self, timeout=30):
        endpoint = '/alarms/active/summary'
        headers = {
            "Accept": "application/json",
        }

        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)
